  ('Play down', '', 'Try to make something seem less important.', 'The Government has tried to [play down] the importance of the minister''s resignation.', '⬇️', array['Phrasal verb','Action','Size, amount & distance','≈ Important']::text[]),
  ('Play off', '', 'Play a game to decide who the winner is.', 'As both teams had the same points, they [played off] to decide the winner.', '🔛', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Play off', 'meaning 2', 'Make people compete against each other so that you benefit.', 'He [played] them [off] against each other to get the best deal.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Play on', '', 'Continue playing a sport though there might be a reason to stop.', 'It looked like a foul, but the referee told them to [play on].', '🔛', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
